//! The RK3588 VEPU580 hardware H.264 encoder (RKVENC): one task per frame, IDR then P frames off one reference,
//! the hardware writing each slice (header included, with its start code) into a bitstream dmabuf.
//!
//! Each frame's register image is generated by `vepu580_setup` the way MPP generates it, then patched by the scene
//! tuner (`vepu580_tune`). Submit / poll / status follow MPP `mpp/hal/rkenc/h264e/hal_h264e_vepu580.c`
//! (`hal_h264e_vepu580_start`, `_wait`, `_ret_task`); buffer sizes follow its `setup_hal_bufs`.

use anyhow::{bail, ensure, Context, Result};

use crate::dma::{DmaBuf, Heap};
use crate::h264;
use crate::jpeg::Sampling;
use crate::rc::RateControl;
use crate::service::{client, Read, Session, Write};
use crate::vepu580_setup::{self as setup, FrameSetup};
use crate::vepu580_tune::Tune;

/// One register field: byte offset of its 32-bit register, lowest bit, width.
#[derive(Clone, Copy, Debug)]
pub struct Field {
    pub addr: u32,
    pub lsb: u32,
    pub width: u32,
}

pub const fn f(addr: u32, lsb: u32, width: u32) -> Field {
    Field { addr, lsb, width }
}

const fn mask(width: u32) -> u32 {
    if width >= 32 {
        u32::MAX
    } else {
        (1 << width) - 1
    }
}

/// The register classes MPP writes, (byte offset, word count), in the order it writes them
/// (`hal_h264e_vepu580_start`: ctl, base, rc_klut, s3, rdo, scl, osd).
pub const CLASSES: [(u32, usize); 7] = [
    (0x0000, 24),
    (0x0280, 94),
    (0x1000, 57),
    (0x1700, 180),
    (0x2000, 122),
    (0x2200, 679),
    (0x3000, 288),
];
const INT_STA: u32 = 0x2c;
const ST_OFFSET: u32 = 0x4000;
const ST_WORDS: usize = 180;

#[derive(Clone)]
pub struct Regs {
    classes: [Vec<u32>; 7],
}

impl Regs {
    pub fn zeroed() -> Box<Self> {
        Box::new(Self {
            classes: CLASSES.map(|(_, n)| vec![0; n]),
        })
    }

    pub fn classes(&self) -> impl Iterator<Item = (u32, &[u32])> {
        CLASSES
            .iter()
            .zip(&self.classes)
            .map(|((offset, _), words)| (*offset, words.as_slice()))
    }

    fn locate(addr: u32) -> (usize, usize) {
        for (i, (base, n)) in CLASSES.iter().enumerate() {
            if addr >= *base && ((addr - base) / 4) < *n as u32 {
                return (i, ((addr - base) / 4) as usize);
            }
        }
        panic!("register {addr:#x} is outside every class");
    }

    pub fn word(&self, addr: u32) -> u32 {
        let (c, i) = Self::locate(addr);
        self.classes[c][i]
    }

    pub fn set_word(&mut self, addr: u32, value: u32) {
        let (c, i) = Self::locate(addr);
        self.classes[c][i] = value;
    }

    pub fn set_byte(&mut self, addr: u32, value: u8) {
        let shift = (addr % 4) * 8;
        let w = self.word(addr & !3);
        self.set_word(addr & !3, (w & !(0xff << shift)) | (value as u32) << shift);
    }

    pub fn set(&mut self, field: Field, value: u32) {
        let m = mask(field.width);
        let w = self.word(field.addr);
        self.set_word(
            field.addr,
            (w & !(m << field.lsb)) | ((value & m) << field.lsb),
        );
    }

    pub fn get(&self, field: Field) -> u32 {
        (self.word(field.addr) >> field.lsb) & mask(field.width)
    }
}

/// The status the kernel copies back after the task: `int_sta` and the status class.
pub struct Status {
    pub int_sta: [u32; 1],
    pub st: [u32; ST_WORDS],
}

impl Status {
    pub fn word(&self, addr: u32) -> u32 {
        self.st[((addr - ST_OFFSET) / 4) as usize]
    }

    pub fn get(&self, field: Field) -> u32 {
        (self.word(field.addr) >> field.lsb) & mask(field.width)
    }
}

const ST_BS_LGTH_L32: u32 = 0x4000;
const ST_QP_SUM: u32 = 0x400c;
/// int_sta: bit-stream overflow, bus write full, bus write error, bus read error, watchdog
const INT_STA_ERRORS: u32 = 0x1f << 4;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct EncoderConfig {
    pub width: u32,
    pub height: u32,
    pub fps: u32,
    pub bitrate_bps: u32,
    /// keyframe interval in frames
    pub gop: u32,
}

/// Smallest frame side the hardware takes (one macroblock).
pub const MIN_SIDE: u32 = 16;
/// Widest frame this port encodes: past 4096 (64-aligned) MPP adds an external line buffer, not ported here.
pub const MAX_WIDTH: u32 = 4096;
/// Tallest frame this port encodes (the same bound MPP's buffers are sized for on this SoC).
pub const MAX_HEIGHT: u32 = 4096;

/// Refuses a size the hardware (as ported) can't encode, saying why.
pub fn check_size(width: u32, height: u32) -> Result<()> {
    ensure!(
        width >= MIN_SIDE && height >= MIN_SIDE,
        "{width}x{height} is smaller than one {MIN_SIDE}x{MIN_SIDE} macroblock"
    );
    ensure!(
        width.next_multiple_of(64) <= MAX_WIDTH,
        "{width}x{height} is wider than {MAX_WIDTH}: MPP needs an external line buffer there, which this crate does not set up"
    );
    ensure!(
        height <= MAX_HEIGHT,
        "{width}x{height} is taller than {MAX_HEIGHT}"
    );
    ensure!(
        width.is_multiple_of(2) && height.is_multiple_of(2),
        "{width}x{height}: 4:2:0 needs an even width and height"
    );
    Ok(())
}

/// One reconstructed frame (the encoder's reference): its FBC pixel buffer and downscaled "thumb".
struct Recon {
    pixel: DmaBuf,
    thumb: DmaBuf,
}

/// What one frame produced.
pub struct Frame {
    pub idr: bool,
    pub qp: u32,
    pub avg_qp: f64,
    pub target_bits: u32,
    pub bits: u32,
    pub moving_scene: bool,
}

pub struct H264Encoder {
    config: EncoderConfig,
    session: Session,
    recon: [Recon; 2],
    /// slot the next frame writes its reconstruction into
    curr_slot: usize,
    out: DmaBuf,
    fbc_header_size: u32,
    frames_since_idr: u32,
    idr_count: u32,
    /// dual-core handshake id the next frame transmits under, and the id each recon slot was written under
    dchs_curr: u32,
    dchs_slot_txid: [u32; 2],
    rc: RateControl,
    tune: Tune,
    force_idr: bool,
    level_idc: u32,
    sps_pps: Vec<u8>,
    aud: Vec<u8>,
}

/// `setup_hal_bufs`: FBC reconstruction needs a 64-aligned width and 16 extra lines.
/// Returns (FBC header size, whole pixel buffer size, thumb size).
pub fn recon_sizes(width: u32, height: u32) -> (u32, u32, u32) {
    let aligned_w = width.next_multiple_of(64);
    let aligned_h = height.next_multiple_of(16) + 16;
    let fbc_header_size = (aligned_w * aligned_h / 64).next_multiple_of(8192);
    let pixel_size = fbc_header_size + aligned_w * aligned_h * 3 / 2;
    let thumb_size = (aligned_w / 64 * aligned_h / 64 * 256).next_multiple_of(8192);
    (fbc_header_size, pixel_size, thumb_size)
}

impl H264Encoder {
    pub fn new(heap: &Heap, config: EncoderConfig) -> Result<Self> {
        check_size(config.width, config.height)?;
        ensure!(
            config.fps > 0 && config.gop > 0 && config.bitrate_bps > 0,
            "fps, gop and bitrate must be positive"
        );
        let (fbc_header_size, pixel_size, thumb_size) = recon_sizes(config.width, config.height);
        let recon = || -> Result<Recon> {
            Ok(Recon {
                pixel: heap.alloc(pixel_size as usize)?,
                thumb: heap.alloc(thumb_size as usize)?,
            })
        };
        let session = Session::new(client::RKVENC).context("opening the H.264 encoder")?;
        // what /proc/mpp_service/*/sessions-info shows: width, height, format, fps in/out, rc mode, bitrate, gop
        let info = |key: u32, flag: u32, value: u32| [key, flag, value, 0];
        let _ = session.send_codec_info(&[
            info(1, 1, config.width),
            info(2, 1, config.height),
            info(3, 2, u32::from_le_bytes(*b"h264")),
            info(4, 1, config.fps),
            info(5, 1, config.fps),
            info(6, 2, u32::from_le_bytes(*b"cbr\0")),
            info(7, 1, config.bitrate_bps),
            info(8, 1, config.gop),
            info(10, 2, u32::from_le_bytes(*b"high")),
        ]);
        let params = h264::StreamParams {
            width: config.width,
            height: config.height,
            fps: config.fps,
        };
        Ok(Self {
            config,
            session,
            recon: [recon()?, recon()?],
            curr_slot: 0,
            // the vendor build's packet buffer: one (16-row aligned) luma plane's worth
            out: heap.alloc(
                (setup::luma_stride(config.width) * setup::luma_rows(config.height)) as usize,
            )?,
            fbc_header_size,
            frames_since_idr: 0,
            idr_count: 0,
            dchs_curr: 0,
            dchs_slot_txid: [0; 2],
            rc: RateControl::new(config.bitrate_bps, config.fps, config.gop),
            tune: Tune::default(),
            force_idr: true,
            level_idc: h264::level_idc(config.width, config.height),
            sps_pps: [h264::sps(params), h264::pps()].concat(),
            aud: h264::aud(),
        })
    }

    pub fn config(&self) -> EncoderConfig {
        self.config
    }

    /// Makes the next frame an IDR (it also follows every `gop` frames, and any failed frame).
    pub fn force_idr(&mut self) {
        self.force_idr = true;
    }

    /// The setup for the next frame, advancing the dual-core handshake ids the way `setup_vepu580_dual_core` does.
    fn frame_setup(
        &mut self,
        src: &DmaBuf,
        sampling: Sampling,
        idr: bool,
        plan: crate::rc::Plan,
    ) -> FrameSetup {
        let refr_slot = 1 - self.curr_slot;
        let (rxe, rxid) = if idr {
            self.dchs_curr = 0;
            (false, 0)
        } else {
            (true, self.dchs_slot_txid[refr_slot])
        };
        let txid = self.dchs_curr;
        self.dchs_slot_txid[self.curr_slot] = txid;
        self.dchs_curr = (self.dchs_curr + 1) % 4;
        let curr = &self.recon[self.curr_slot];
        let refr = if idr { curr } else { &self.recon[refr_slot] };
        FrameSetup {
            width: self.config.width,
            height: self.config.height,
            sampling,
            idr,
            frame_num: self.frames_since_idr,
            idr_pic_id: self.idr_count,
            poc_lsb: 2 * self.frames_since_idr,
            plan,
            dchs_txid: txid,
            dchs_rxid: rxid,
            dchs_rxe: rxe,
            level_idc: self.level_idc,
            src_fd: src.fd(),
            recn: (curr.pixel.fd(), curr.thumb.fd()),
            refr: (refr.pixel.fd(), refr.thumb.fd()),
            fbc_header_size: self.fbc_header_size,
            out_fd: self.out.fd(),
            out_size: self.out.len() as u32,
        }
    }

    /// Encodes one YUV frame in `src` (the JPEG decoder's output) into one Annex-B access unit: an access unit
    /// delimiter, then on an IDR the SPS and PPS, then the slice.
    pub fn encode(&mut self, src: &DmaBuf, sampling: Sampling, out: &mut Vec<u8>) -> Result<Frame> {
        let idr = self.force_idr || self.frames_since_idr >= self.config.gop;
        if idr {
            self.frames_since_idr = 0;
        }
        let plan = self.rc.plan(idr);
        let frame = self.frame_setup(src, sampling, idr, plan);
        let (mut regs, offsets) = setup::generate(&frame);
        self.tune.patch(&mut regs, idr);
        let mut status = Status {
            int_sta: [0],
            st: [0; ST_WORDS],
        };
        let writes: Vec<Write> = regs
            .classes()
            .map(|(offset, words)| Write { offset, words })
            .collect();
        let result = self.session.run(
            &writes,
            &mut [
                Read {
                    offset: INT_STA,
                    words: &mut status.int_sta,
                },
                Read {
                    offset: ST_OFFSET,
                    words: &mut status.st,
                },
            ],
            &offsets,
        );
        // anything that goes wrong leaves no trustworthy reference: start over at an IDR
        self.force_idr = true;
        result?;
        let int_sta = status.int_sta[0];
        ensure!(
            int_sta & 1 != 0 && int_sta & INT_STA_ERRORS == 0,
            "H.264 encode failed: interrupt status {int_sta:#06x}"
        );
        let len = status.word(ST_BS_LGTH_L32) as usize;
        if len <= 4 || len > self.out.len() {
            bail!("H.264 encoder reported a {len}-byte slice");
        }
        out.clear();
        out.extend_from_slice(&self.aud);
        if idr {
            out.extend_from_slice(&self.sps_pps);
        }
        self.out.read(len, |slice| out.extend_from_slice(slice))?;
        ensure!(
            out[out.len() - len..].starts_with(&[0, 0, 0, 1]),
            "the encoder's slice has no start code"
        );

        let mbs = self.config.width.div_ceil(16) * self.config.height.div_ceil(16);
        let avg_qp = status.word(ST_QP_SUM) as f64 / mbs as f64;
        let bits = (len * 8) as u32;
        self.rc.update(idr, plan, bits, avg_qp);
        self.tune.update(&status);
        if idr {
            self.idr_count = (self.idr_count + 1) & 0xffff;
        }
        self.frames_since_idr += 1;
        self.curr_slot = 1 - self.curr_slot;
        self.force_idr = false;
        Ok(Frame {
            idr,
            qp: plan.qp,
            avg_qp,
            target_bits: plan.target_bits,
            bits,
            moving_scene: self.tune.moving_scene(),
        })
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::rc::Plan;
    use crate::vepu580_fixtures::{Capture, Inputs, CAPTURES, IDR_1280X720, P_1280X720};

    /// The buffer-address registers: dmabuf fds, which differ run to run.
    fn is_fd(addr: u32) -> bool {
        (0x280..0x2c0).contains(&addr)
    }

    /// The image this crate generates for one captured frame's inputs, tuner in its starting (static) state.
    fn generated(c: &Capture, inputs: &Inputs, idr: bool) -> Box<Regs> {
        let mbs = (c.width.div_ceil(16) * c.height.div_ceil(16)) as u64;
        // a bit target that gives back exactly the captured ctu_ebit
        let target_bits = ((inputs.ctu_ebit as u64 * mbs).div_ceil(16)) as u32;
        let p = FrameSetup {
            width: c.width,
            height: c.height,
            sampling: Sampling::Yuv420,
            idr,
            frame_num: inputs.frame_num,
            idr_pic_id: inputs.idr_pic_id,
            poc_lsb: inputs.poc_lsb,
            plan: Plan {
                qp: inputs.qp,
                target_bits,
            },
            dchs_txid: inputs.dchs_txid,
            dchs_rxid: inputs.dchs_rxid,
            dchs_rxe: inputs.dchs_rxe != 0,
            level_idc: h264::level_idc(c.width, c.height),
            src_fd: 0,
            recn: (0, 0),
            refr: (0, 0),
            fbc_header_size: 0,
            out_fd: 0,
            out_size: 0,
        };
        let (mut regs, _) = setup::generate(&p);
        Tune::default().patch(&mut regs, idr);
        regs
    }

    fn mismatches(c: &Capture, k: usize) -> Vec<String> {
        let (inputs, diff) = &c.frames[k];
        let base: &[(u32, u32)] = if k == 0 { &IDR_1280X720 } else { &P_1280X720 };
        let mut want: std::collections::BTreeMap<u32, u32> = base.iter().copied().collect();
        want.extend(diff.iter().copied());
        let regs = generated(c, inputs, k == 0);
        let mut bad = Vec::new();
        for (offset, words) in regs.classes() {
            for (i, &got) in words.iter().enumerate() {
                let addr = offset + 4 * i as u32;
                if is_fd(addr) {
                    continue;
                }
                // the vendor image has no OSD class (MPP writes zeros there)
                let expect = want.get(&addr).copied().unwrap_or(0);
                if got != expect {
                    bad.push(format!(
                        "{}x{} {} {addr:#06x}: generated {got:#010x}, vendor {expect:#010x}",
                        c.width,
                        c.height,
                        if k == 0 { "IDR" } else { "P" }
                    ));
                }
            }
        }
        bad
    }

    #[test]
    fn generated_registers_match_the_vendor_at_1280x720() {
        let c = CAPTURES
            .iter()
            .find(|c| (c.width, c.height) == (1280, 720))
            .unwrap();
        let bad: Vec<String> = (0..2).flat_map(|k| mismatches(c, k)).collect();
        assert!(bad.is_empty(), "{}", bad.join("\n"));
    }

    #[test]
    fn generated_registers_match_the_vendor_at_every_captured_size() {
        let bad: Vec<String> = CAPTURES
            .iter()
            .flat_map(|c| (0..2).flat_map(move |k| mismatches(c, k)))
            .collect();
        assert!(bad.is_empty(), "{}", bad.join("\n"));
        assert!(CAPTURES.len() >= 8);
    }

    #[test]
    fn sizes_outside_the_port_are_refused() {
        for (w, h) in [
            (1280, 720),
            (1920, 1080),
            (640, 360),
            (16, 16),
            (4096, 2160),
        ] {
            check_size(w, h).unwrap();
        }
        assert!(format!("{:#}", check_size(8, 720).unwrap_err()).contains("macroblock"));
        assert!(
            format!("{:#}", check_size(4100, 720).unwrap_err()).contains("external line buffer")
        );
        assert!(format!("{:#}", check_size(1280, 5000).unwrap_err()).contains("taller"));
        assert!(format!("{:#}", check_size(1281, 720).unwrap_err()).contains("even"));
    }

    #[test]
    fn recon_buffer_offsets_match_the_vendor() {
        // the vendor's fbc header offsets (regs 164/166): 0x4000 at 720p, 0xa000 at 1080p, 0x2000 at 480p
        assert_eq!(recon_sizes(1280, 720).0, 0x4000);
        assert_eq!(recon_sizes(1920, 1080).0, 0xa000);
        assert_eq!(recon_sizes(640, 480).0, 0x2000);
        assert_eq!(recon_sizes(1280, 960).0, 0x6000);
    }
}
